#!/usr/bin/env python3
import json, sys

path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 400

def trunc(s, n=maxlen):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)-n} more chars]"

with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"[PARSE ERROR: {e}]")
            continue
        ts = obj.get("timestamp", "")
        typ = obj.get("type", obj.get("role", "?"))
        msg = obj.get("message", obj)
        content = msg.get("content") if isinstance(msg, dict) else None
        if isinstance(content, str):
            print(f"{ts} [{typ}] TEXT: {trunc(content)}")
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    print(f"{ts} [{typ}] {trunc(c)}")
                    continue
                ctype = c.get("type")
                if ctype == "text":
                    print(f"{ts} [{typ}] TEXT: {trunc(c.get('text',''))}")
                elif ctype == "tool_use":
                    print(f"{ts} [{typ}] TOOL_USE {c.get('name')}: {trunc(json.dumps(c.get('input',{})))}")
                elif ctype == "tool_result":
                    cc = c.get("content")
                    print(f"{ts} [{typ}] TOOL_RESULT: {trunc(json.dumps(cc) if not isinstance(cc,str) else cc)}")
                else:
                    print(f"{ts} [{typ}] {ctype}: {trunc(json.dumps(c))}")
        else:
            print(f"{ts} [{typ}] {trunc(json.dumps(obj))}")

