import json, sys

path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 500

def trunc(s, n=maxlen):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)-n} more chars]"

with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        typ = obj.get("type")
        if typ not in ("user", "assistant"):
            continue
        msg = obj.get("message", obj)
        content = msg.get("content") if isinstance(msg, dict) else None
        if isinstance(content, str):
            if content.strip():
                print(f"[{typ}] {trunc(content)}")
            continue
        if isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get("type") == "text" and c.get("text","").strip():
                    print(f"[{typ}] {trunc(c['text'])}")

